	ld a, [wSfxHighPri]         ; 4337: FA 0B DF  a high-priority SFX is running
	or a                        ; 433A: B7
	ret nz                      ; 433B: C0
.startSfx:
	xor a                       ; 433C: AF
	ld [wSfxTimer], a           ; 433D: EA 03 DF
	ld [wSfxTranspose], a       ; 4340: EA 02 DF
	ld [wSfxWaitAdd], a         ; 4343: EA 06 DF
	ld a, [wSfxOwnCh1]          ; 4346: FA 07 DF
	or a                        ; 4349: B7
	jp z, .freeCh2              ; 434A: CA 53 43
	xor a                       ; 434D: AF
	ldh [rNR12], a              ; 434E: E0 12
	ld [wSfxOwnCh1], a          ; 4350: EA 07 DF
.freeCh2:
	ld a, [wSfxOwnCh2]          ; 4353: FA 08 DF
	or a                        ; 4356: B7
	jp z, .freeCh3              ; 4357: CA 60 43
	xor a                       ; 435A: AF
	ldh [rNR22], a              ; 435B: E0 17
	ld [wSfxOwnCh2], a          ; 435D: EA 08 DF
.freeCh3:
	ld a, [wSfxOwnCh3]          ; 4360: FA 09 DF
	or a                        ; 4363: B7
	jp z, .freeCh4              ; 4364: CA 6D 43
	xor a                       ; 4367: AF
	ldh [rNR32], a              ; 4368: E0 1C
	ld [wSfxOwnCh3], a          ; 436A: EA 09 DF
.freeCh4:
	ld a, [wSfxOwnCh4]          ; 436D: FA 0A DF
	or a                        ; 4370: B7
	jp z, .setSfx               ; 4371: CA 7A 43
	xor a                       ; 4374: AF
	ldh [rNR42], a              ; 4375: E0 21
	ld [wSfxOwnCh4], a          ; 4377: EA 0A DF
.setSfx:
	ld a, b                     ; 437A: 78
	and $40                     ; 437B: E6 40
	ld [wSfxHighPri], a         ; 437D: EA 0B DF
	ld a, b                     ; 4380: 78
	and $3F                     ; 4381: E6 3F
	add a, a                    ; 4383: 87
	ld e, a                     ; 4384: 5F
	ld d, $00                   ; 4385: 16 00
	ld hl, SoundTable           ; 4387: 21 26 4A
	add hl, de                  ; 438A: 19
	ld a, [hli]                 ; 438B: 2A
	ld [wSfxPtr], a             ; 438C: EA 04 DF
	ld a, [hli]                 ; 438F: 2A
	ld [wSfxPtr + 1], a         ; 4390: EA 05 DF
	ld a, $77                   ; 4393: 3E 77
	ldh [rNR50], a              ; 4395: E0 24
	ld a, $FF                   ; 4397: 3E FF
	ldh [rNR51], a              ; 4399: E0 25
	ld a, $01                   ; 439B: 3E 01
	ld [wSfxTimer], a           ; 439D: EA 03 DF
	ret                         ; 43A0: C9
.playMusic:
	call SndSilence             ; 43A1: CD FA 43
	ld [wMusTimer], a           ; 43A4: EA 11 DF
	ld [wMusUnused13], a        ; 43A7: EA 13 DF
	ld [wMusPaused], a          ; 43AA: EA 14 DF
	dec a                       ; 43AD: 3D
	ld [wMusUnused12], a        ; 43AE: EA 12 DF
	ld [wMusWave], a            ; 43B1: EA 15 DF
	ld a, b                     ; 43B4: 78

MusicStart:
	and $3F                     ; 43B5: E6 3F
	add a, a                    ; 43B7: 87
	ld e, a                     ; 43B8: 5F
	ld d, $00                   ; 43B9: 16 00
	ld hl, SoundTable           ; 43BB: 21 26 4A
